  1	/**
  2	 * Entity-mutation gate — a pluggable interceptor pipeline that sits in front of
  3	 * every user-facing entity write (create/update/delete + watcher promotion).
  4	 *
  5	 * Core mutation code (manage_entity, entity-management.updateEntity,
  6	 * promote-keyed-entities, complete-window) is POLICY-BLIND: it builds one
  7	 * `EntityMutationRequest`, calls `runMutationGate`, and acts on the decision. It
  8	 * never imports the approval ACL or any specific policy module. New cross-cutting
  9	 * gates (quota, rate limits, …) are added as ONE new interceptor file whose
 10	 * exported interceptor is appended to `BUILTIN_INTERCEPTORS` below — with zero
 11	 * edits to core mutation code.
 12	 *
 13	 * Chaining semantics (deterministic, order = registration order):
 14	 *  - create/delete: the first `deny` wins; the first `defer` short-circuits (its
 15	 *    `DeferredMutation` is returned); otherwise `allow`.
 16	 *  - update: any `deny` on a field wins immediately; otherwise the per-field
 17	 *    `requireApproval` sets are UNION-ed across all interceptors (empty ⇒ allow).
 18	 *
 19	 * A `defer` never writes on the caller's transaction. The interceptor hands back
 20	 * a `DeferredMutation` whose `queue()` closure the CORE runs strictly POST-COMMIT
 21	 * (repo invariant: approvals + their events never ride the caller's tx).
 22	 *
 23	 * Import-cycle note: the static edge chain is gate → approval-interceptor →
 24	 * entity-field-approval → entity-management → gate (circular). This is safe
 25	 * because every cross-module use inside the cycle happens at CALL time, never at
 26	 * module-init, and this module's public API is hoisted `function` declarations —
 27	 * so the circular partial-module view entity-management receives is complete.
 28	 * By the time this module's own body initializes `BUILTIN_INTERCEPTORS`, the
 29	 * interceptor module has fully evaluated (it is this module's dependency). Keep
 30	 * the exports below as `function` declarations (not const arrows) so the
 31	 * hoisting guarantee holds. The interceptor import MUST stay static: the
 32	 * production esbuild bundle (docker/app → dist/server.bundle.mjs) cannot follow
 33	 * a variable-specifier dynamic import and would ship a gate with no
 34	 * interceptors.
 35	 *
 36	 * Multi-replica safety: the registry is code-defined and identical on every pod
 37	 * (no shared mutable state affecting decisions).
 38	 */
 39	
 40	import type { ApprovalAttribution } from "@lobu/core/contracts/interaction-envelope";
 41	import type { DbClient } from "../db/client";
 42	import type { Env } from "../index";
 43	import type { ToolContext } from "../tools/registry";
 44	import type { EntityData } from "../utils/entity-management";
 45	import {
 46		approvalInterceptor,
 47		buildCreateDeferral,
 48		buildFieldChangeDeferral,
 49	} from "./approval-interceptor";
 50	
 51	export type MutationPrincipalKind = "user" | "agent" | "watcher";
 52	
 53	/** Attribution for a deferred (queued-for-approval) mutation. */
 54	export type MutationAttribution = ApprovalAttribution;
 55	
 56	/** Field ownership as seen by an update request ("human" pins the value). */
 57	export type FieldOwner = "human" | "none";
 58	
 59	interface EntityMutationBase {
 60		organizationId: string;
 61		principalKind: MutationPrincipalKind;
 62		/** Caller's DbClient or open transaction — interceptors query policy on it. */
 63		sql: DbClient;
 64		/** Attribution + watcher id used by an interceptor to label a deferral. */
 65		attribution: MutationAttribution;
 66		watcherId?: number | null;
 67		/**
 68		 * Stable identity of the acting non-human principal, for per-principal policy
 69		 * matching (a policy row may target one agent or watcher). Agent → agent id;
 70		 * watcher → `watcher:<id>`; system/automation token (no agent id) → null.
 71		 * Null means "any principal of this kind". Plumbed here now; consumed by the
 72		 * per-principal resolver in a later commit.
 73		 */
 74		principalId?: string | null;
 75		/**
 76		 * The OWNING AGENT of a watcher, when the acting principal is a watcher. The
 77		 * write is then governed by BOTH the watcher's own rows AND its agent's,
 78		 * folded max-restrictive — so an agent's envelope binds its watcher, while a
 79		 * pre-existing watcher-specific restriction can only tighten (the agent
 80		 * envelope never loosens it away). Null when not a watcher, or a watcher with
 81		 * no agent. `watchers.agent_id` is the sole principal-ownership edge, so this
 82		 * is the only ancestor a write ever folds.
 83		 */
 84		ownerAgentId?: string | null;
 85		/**
 86		 * False iff the acting principal is a watcher whose owning agent could not be
 87		 * resolved (its row is gone). Threaded to the gate so it FAILS CLOSED (deny)
 88		 * rather than run the write as an unowned watcher against the looser org default.
 89		 * Defaults true (agent/user writes, and watchers whose owner resolved).
 90		 */
 91		ownerResolved?: boolean;
 92		/**
 93		 * The watcher-run window that produced this mutation, if any. Threaded so a
 94		 * deferred approval lands on the `runs.window_id` COLUMN — that's what groups a
 95		 * run's N proposals into ONE batch approval card, and (with the window in the
 96		 * dedup key) keeps identical proposals from different windows distinct.
 97		 */
 98		windowId?: number | null;
 99	}
100	
101	export interface CreateMutationRequest extends EntityMutationBase {
102		action: "create";
103		entityTypeSlug: string;
104		entityData: EntityData;
105		/** Snapshot payload shown on the approval card. */
106		proposal: Record<string, unknown>;
107	}
108	
109	export interface DeleteMutationRequest extends EntityMutationBase {
110		action: "delete";
111		entityTypeSlug: string;
112		entityId: number;
113		entityOrgId: string | null;
114		forceDeleteTree?: boolean;
115		/** Snapshot of the entity being deleted, for the approval card. */
116		current: Record<string, unknown>;
117	}
118	
119	export interface UpdateMutationRequest extends EntityMutationBase {
120		action: "update";
121		entityTypeSlug: string;
122		entityId: number;
123		entityOrgId?: string | null;
124		/** field path (incl. reserved $-attributes) -> current owner. */
125		fields: Record<string, FieldOwner>;
126	}
127	
128	export type EntityMutationRequest =
129		| CreateMutationRequest
130		| DeleteMutationRequest
131		| UpdateMutationRequest;
132	
133	/**
134	 * A mutation an interceptor held back. `queue()` is called POST-COMMIT by the
135	 * core to durably record the approval (run + event + notification) and returns
136	 * the ids/url the call site folds into its "approval queued" result. `display`
137	 * carries whatever the call site needs to assemble that result without knowing
138	 * how the approval was built.
139	 */
140	export interface DeferredMutation {
141		queue: (
142			ctx: ToolContext,
143			env: Env,
144		) => Promise<{ runId: number; eventId: number; approvalUrl?: string }>;
145		display: {
146			action: "create" | "update" | "delete";
147			attribution: MutationAttribution;
148			proposal?: Record<string, unknown>;
149			current?: Record<string, unknown>;
150			fields?: Record<string, unknown>;
151		};
152	}
153	
154	export type CreateOrDeleteDecision =
155		| { outcome: "allow" }
156		| { outcome: "deny"; reason: string }
157		| { outcome: "defer"; deferred: DeferredMutation };
158	
159	export type UpdateDecision =
160		| { outcome: "deny"; reason: string }
161		| { outcome: "fields"; requireApproval: Set<string> };
162	
163	/**
164	 * One cross-cutting gate. An interceptor inspects a request and returns either a
165	 * create/delete decision or an update decision, matching the request action.
166	 * Returning `null` means "no opinion" (pass-through).
167	 */
168	export interface MutationInterceptor {
169		name: string;
170		evaluate: (
171			req: EntityMutationRequest,
172		) => Promise<CreateOrDeleteDecision | UpdateDecision | null>;
173	}
174	
175	/**
176	 * Interceptors every deployment runs, in order. Statically imported so the
177	 * production bundle includes them (see the import-cycle note above).
178	 */
179	const BUILTIN_INTERCEPTORS: readonly MutationInterceptor[] = [
180		approvalInterceptor,
181	];
182	
183	const registry: MutationInterceptor[] = [...BUILTIN_INTERCEPTORS];
184	
185	/** Append an interceptor after the builtins. Idempotent by name. */
186	export function registerMutationInterceptor(
187		interceptor: MutationInterceptor,
188	): void {
189		if (registry.some((i) => i.name === interceptor.name)) return;
190		registry.push(interceptor);
191	}
192	
193	/**
194	 * Package a blocked field-change discovered LATE (after the row lock + merge,
195	 * when the blocked values are finally known) as a POST-COMMIT deferred mutation.
196	 * Thin wrapper so core mutation code imports only the gate, never the ACL.
197	 */
198	export function deferEntityFieldChange(args: {
199		entityId: number;
200		fields: Record<string, unknown>;
201		current: Record<string, unknown>;
202		attribution: MutationAttribution;
203		watcherId?: number | null;
204		/** Groups this proposal's run into a per-window batch approval card. */
205		windowId?: number | null;
206	}): DeferredMutation {
207		return buildFieldChangeDeferral(args);
208	}
209	
210	/** Package a policy-held create as a POST-COMMIT deferred mutation. */
211	export function deferEntityCreate(args: {
212		entityData: EntityData;
213		proposal: Record<string, unknown>;
214		attribution: MutationAttribution;
215		watcherId?: number | null;
216		/** Groups this proposal's run into a per-window batch approval card. */
217		windowId?: number | null;
218	}): DeferredMutation {
219		return buildCreateDeferral(args);
220	}
221	
222	function isUpdateDecision(
223		d: CreateOrDeleteDecision | UpdateDecision,
224	): d is UpdateDecision {
225		return d.outcome === "deny" || d.outcome === "fields";
226	}
227	
228	/**
229	 * Run every registered interceptor against `req` and fold the results per the
230	 * chaining semantics documented at the top of this file.
231	 */
232	export async function runMutationGate(
233		req: CreateMutationRequest | DeleteMutationRequest,
234	): Promise<CreateOrDeleteDecision>;
235	export async function runMutationGate(
236		req: UpdateMutationRequest,
237	): Promise<UpdateDecision>;
238	export async function runMutationGate(
239		req: EntityMutationRequest,
240	): Promise<CreateOrDeleteDecision | UpdateDecision> {
241		if (req.action === "update") {
242			const requireApproval = new Set<string>();
243			for (const interceptor of registry) {
244				const decision = await interceptor.evaluate(req);
245				if (!decision) continue;
246				if (decision.outcome === "deny") return decision;
247				if (isUpdateDecision(decision)) {
248					for (const field of decision.requireApproval) requireApproval.add(field);
249				}
250			}
251			return { outcome: "fields", requireApproval };
252		}
253	
254		for (const interceptor of registry) {
255			const decision = await interceptor.evaluate(req);
256			if (!decision) continue;
257			if (decision.outcome === "deny") return decision;
258			if (decision.outcome === "defer") return decision;
259		}
260		return { outcome: "allow" };
  1	/**
  2	 * Relationship Validation Helpers
  3	 *
  4	 * Validates entity relationship constraints: self-reference, confidence bounds,
  5	 * source enums, symmetric canonicalization, scope enforcement, type-pair rules, and
  6	 * duplicate edge detection.
  7	 */
  8	
  9	import { type DbClient, getDb } from '../db/client';
 10	import type { Env } from '../index';
 11	import type { ToolContext } from '../tools/registry';
 12	
 13	// Valid relationship sources
 14	const RELATIONSHIP_SOURCES = ['ui', 'llm', 'feed', 'api'] as const;
 15	type RelationshipSource = (typeof RELATIONSHIP_SOURCES)[number];
 16	
 17	/**
 18	 * Validate that a relationship does not reference itself.
 19	 */
 20	export function validateNoSelfReference(fromId: number, toId: number): void {
 21	  if (fromId === toId) {
 22	    throw new Error('Self-referencing relationships are not allowed');
 23	  }
 24	}
 25	
 26	/**
 27	 * Validate confidence is in [0, 1] range.
 28	 */
 29	export function validateConfidence(confidence: number | undefined | null): void {
 30	  if (confidence === undefined || confidence === null) return;
 31	  if (typeof confidence !== 'number' || confidence < 0 || confidence > 1) {
 32	    throw new Error('Confidence must be a number between 0 and 1');
 33	  }
 34	}
 35	
 36	/**
 37	 * Validate source is a known enum value.
 38	 */
 39	export function validateSource(source: string | undefined | null): void {
 40	  if (source === undefined || source === null) return;
 41	  if (!RELATIONSHIP_SOURCES.includes(source as RelationshipSource)) {
 42	    throw new Error(
 43	      `Invalid source "${source}". Must be one of: ${RELATIONSHIP_SOURCES.join(', ')}`
 44	    );
 45	  }
 46	}
 47	
 48	/**
 49	 * Canonicalize a symmetric edge so from_entity_id < to_entity_id.
 50	 */
 51	export function canonicalizeSymmetricEdge(
 52	  fromId: number,
 53	  toId: number
 54	): { from: number; to: number } {
 55	  return fromId <= toId ? { from: fromId, to: toId } : { from: toId, to: fromId };
 56	}
 57	
 58	/**
 59	 * Validate scope rule for a relationship.
 60	 *
 61	 * The from_entity must belong to the caller's organization (relationships are
 62	 * always authored from the source's org). The to_entity may be either in the
 63	 * same org or in a public-catalog org (`organization.visibility='public'`),
 64	 * which lets a tenant's relationship reference canonical world entities like
 65	 * HMRC or Barclays without copying them locally.
 66	 *
 67	 * Public → tenant references are forbidden — public catalogs never reach into
 68	 * private orgs. The relationship row's organization_id always matches the
 69	 * source's org (the caller's), keeping the assertion under the caller's
 70	 * delete/visibility control.
 71	 */
 72	export async function validateScopeRule(
 73	  fromEntityId: number,
 74	  toEntityId: number,
 75	  _env: Env,
 76	  ctx: ToolContext
 77	): Promise<void> {
 78	  const sql = getDb();
 79	
 80	  const rows = await sql`
 81	    SELECT e.id, e.organization_id, o.visibility
 82	    FROM entities e
 83	    LEFT JOIN organization o ON o.id = e.organization_id
 84	    WHERE e.id IN (${fromEntityId}, ${toEntityId})
 85	  `;
 86	
 87	  if (rows.length < 2) {
 88	    const foundIds = rows.map((r) => r.id);
 89	    const missingId = [fromEntityId, toEntityId].find((id) => !foundIds.includes(id));
 90	    throw new Error(`Entity ${missingId} not found`);
 91	  }
 92	
 93	  const fromEntity = rows.find((r) => Number(r.id) === fromEntityId)!;
 94	  const toEntity = rows.find((r) => Number(r.id) === toEntityId)!;
 95	
 96	  // Source must always be in the caller's org — you can't author relationships
 97	  // *from* someone else's entity.
 98	  if (String(fromEntity.organization_id) !== ctx.organizationId) {
 99	    throw new Error(`Entity ${fromEntityId} does not belong to your organization`);
100	  }
101	
102	  // Target may be same-org OR a public-catalog entity. Anything else (a
103	  // private org you don't control) is rejected.
104	  const toOrgId = String(toEntity.organization_id);
105	  const toVisibility = String(toEntity.visibility ?? 'private');
106	  if (toOrgId !== ctx.organizationId && toVisibility !== 'public') {
107	    throw new Error(
108	      `Entity ${toEntityId} is in a private organization that does not belong to you. Cross-org references are only allowed to entities in public catalogs.`
109	    );
110	  }
111	}
112	
113	/**
114	 * Validate that the relationship type allows the given entity type pair.
115	 * For symmetric types, checks both directions.
116	 */
117	export async function validateTypeRule(
118	  relationshipTypeId: number,
119	  fromEntityId: number,
120	  toEntityId: number,
121	  sql: DbClient
122	): Promise<void> {
123	  // Get the relationship type to check if it's symmetric
124	  const typeRows = await sql`
125	    SELECT is_symmetric
126	    FROM entity_relationship_types
127	    WHERE id = ${relationshipTypeId}
128	      AND deleted_at IS NULL
129	  `;
130	  if (typeRows.length === 0) {
131	    throw new Error(`Relationship type ${relationshipTypeId} not found`);
132	  }
133	  const isSymmetric = Boolean(typeRows[0].is_symmetric);
134	
135	  // Get entity types for both entities
136	  const entityRows = await sql`
137	    SELECT e.id, et.slug AS entity_type
138	    FROM entities e
139	    JOIN entity_types et ON et.id = e.entity_type_id
140	    WHERE e.id IN (${fromEntityId}, ${toEntityId})
141	  `;
142	  const fromEntityType = String(entityRows.find((r) => Number(r.id) === fromEntityId)?.entity_type);
143	  const toEntityType = String(entityRows.find((r) => Number(r.id) === toEntityId)?.entity_type);
144	
145	  // Check if there are any rules for this relationship type
146	  const ruleRows = await sql`
147	    SELECT source_entity_type_slug, target_entity_type_slug
148	    FROM entity_relationship_type_rules
149	    WHERE relationship_type_id = ${relationshipTypeId}
150	      AND deleted_at IS NULL
151	  `;
152	
153	  // No rules = any pair is allowed
154	  if (ruleRows.length === 0) return;
155	
156	  // Check if the pair matches any rule (check both directions for symmetric types)
157	  const matches = ruleRows.some((rule) => {
158	    const srcSlug = String(rule.source_entity_type_slug);
159	    const tgtSlug = String(rule.target_entity_type_slug);
160	
161	    if (srcSlug === fromEntityType && tgtSlug === toEntityType) return true;
162	    if (isSymmetric && srcSlug === toEntityType && tgtSlug === fromEntityType) return true;
163	    return false;
164	  });
165	
166	  if (!matches) {
167	    throw new Error(
168	      `Relationship type ${relationshipTypeId} does not allow ${fromEntityType} → ${toEntityType}`
169	    );
170	  }
171	}
172	
173	/**
174	 * Check for duplicate active edge between two entities of the same type.
175	 */
176	export async function checkDuplicateEdge(
177	  fromId: number,
178	  toId: number,
179	  typeId: number,
180	  sql: DbClient
181	): Promise<void> {
182	  const existing = await sql`
183	    SELECT id FROM entity_relationships
184	    WHERE from_entity_id = ${fromId}
185	      AND to_entity_id = ${toId}
186	      AND relationship_type_id = ${typeId}
187	      AND deleted_at IS NULL
188	    LIMIT 1
189	  `;
190	  if (existing.length > 0) {
191	    throw new Error(
192	      `An active relationship of this type already exists between entities ${fromId} and ${toId}`
193	    );
194	  }
195	}
  1	/**
  2	 * Helpers for writing the user's $member entity + entity_identities rows.
  3	 *
  4	 * Used by the signup hook to populate the identity graph so the gateway can
  5	 * later route inbound messages back to the right user's personal org via a
  6	 * single entity_identities lookup.
  7	 */
  8	
  9	import { normalizeSlackUserId, SLACK_IDENTITY } from "@lobu/connectors/slack-identity";
 10	import { fetchUserInfoWithRaw } from "../connect/oauth-providers";
 11	import { getDb } from "../db/client";
 12	import {
 13		type ResolvedTenantMember,
 14		resolveMemberOrgsForUser,
 15	} from "../identity/member-orgs";
 16	import logger from "../utils/logger";
 17	import {
 18		ensureMemberEntity,
 19		resolveMemberSchemaFields,
 20	} from "../utils/member-entity";
 21	import { getEnabledLoginProviderConfigs } from "./config";
 22	
 23	const log = logger.child({ module: "auth-subject-identities" });
 24	
 25	interface PersonalSubject {
 26		userId: string;
 27		email: string;
 28		name?: string | null;
 29		image?: string | null;
 30		/**
 31		 * Role recorded on a NEWLY created `$member` (ignored when the entity already
 32		 * exists — ensureMemberEntity never rewrites the role of an existing member).
 33		 * Defaults to `owner` for the personal-org sign-up path; the backfill passes
 34		 * the member row's actual role so a drifted non-owner is not minted as owner.
 35		 */
 36		role?: string;
 37	}
 38	
 39	interface IdentityRow {
 40		namespace: string;
 41		identifier: string;
 42	}
 43	
 44	type Sql = ReturnType<typeof getDb>;
 45	
 46	/**
 47	 * Insert (or no-op on conflict) entity_identities rows pointing at the given
 48	 * member entity. The unique index on (organization_id, namespace, identifier)
 49	 * WHERE deleted_at IS NULL guards against duplicates.
 50	 */
 51	async function writeIdentities(
 52		sql: Sql,
 53		organizationId: string,
 54		memberEntityId: number,
 55		source: string,
 56		rows: IdentityRow[],
 57	): Promise<void> {
 58		for (const row of rows) {
 59			await sql`
 60	      INSERT INTO entity_identities (
 61	        organization_id, entity_id, namespace, identifier, source_connector
 62	      ) VALUES (
 63	        ${organizationId}, ${memberEntityId}, ${row.namespace}, ${row.identifier}, ${source}
 64	      )
 65	      ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
 66	      DO NOTHING
 67	    `;
 68		}
 69	}
 70	
 71	/**
 72	 * Point a workspace-scoped chat identity at the user's `$member`, taking it over
 73	 * from a `person` entity when one already owns it.
 74	 *
 75	 * Why an UPDATE and not another INSERT: `entity_identities` has a live-unique
 76	 * index on `(organization_id, namespace, identifier)`, so the claim exists at
 77	 * most once. `writeIdentities`' `ON CONFLICT DO NOTHING` therefore SILENTLY LOSES
 78	 * whenever the ACL sync minted a `person` for this workspace user before the
 79	 * human ever signed in — which is the normal ordering, since channel sync runs
 80	 * on a timer and sign-in is a one-off. The gate only ever resolves a `$member`
 81	 * (channel-visibility.ts), so leaving the claim on the `person` hides every
 82	 * enforced channel from its real owner.
 83	 *
 84	 * Re-pointing the claim is sufficient on its own: the ACL graph builder resolves
 85	 * members by whoever owns the identity (`resolveMembers` is deliberately
 86	 * type-agnostic) and reconciles `member_of` edges from that entity on the next
 87	 * sync tick, so the edges follow the claim. Writing edges here by hand would be
 88	 * undone by that same reconcile.
 89	 *
 90	 * SAFETY: only ever called with an identity proven by the provider's own OIDC
 91	 * token for THIS user, and only for an org the user is already a better-auth
 92	 * member of. It never grants org membership, and it never matches on a
 93	 * user-editable field such as a Slack profile email — a workspace admin can set
 94	 * those, which would let an attacker attach their `U…` to a victim's `$member`.
 95	 *
 96	 * The takeover is scoped to `person` entities. A claim already held by another
 97	 * `$member` is a genuine identity conflict (two humans, one Slack id) and is
 98	 * left alone — fail closed, never steal.
 99	 */
100	async function adoptSlackIdentityOntoMember(
101		sql: Sql,
102		organizationId: string,
103		memberEntityId: number,
104		identifier: string,
105	): Promise<"created" | "adopted" | "already-owned" | "conflict"> {
106		const inserted = await sql<{ id: number }>`
107	    INSERT INTO entity_identities (
108	      organization_id, entity_id, namespace, identifier, source_connector
109	    ) VALUES (
110	      ${organizationId}, ${memberEntityId}, ${SLACK_IDENTITY.USER_ID}, ${identifier}, 'auth:signup'
111	    )
112	    ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
113	    DO NOTHING
114	    RETURNING id
115	  `;
116		if (inserted.length > 0) return "created";
117	
118		// Take over only from a `person`; a `$member` holder means two humans claim
119		// one workspace id, which must not be silently reassigned.
120		const adopted = await sql<{ id: number }>`
121	    UPDATE entity_identities ei
122	    SET entity_id = ${memberEntityId},
123	        source_connector = 'auth:signup',
124	        -- Keep a trail back to the person we took this from, matching the
125	        -- convention in entity-merge.ts (COALESCE so a re-run never overwrites
126	        -- the ORIGINAL owner with an intermediate one).
127	        merged_from_entity_id = COALESCE(ei.merged_from_entity_id, ei.entity_id),
128	        updated_at = current_timestamp
129	    FROM entities e
130	    JOIN entity_types et
131	      ON et.id = e.entity_type_id
132	     AND et.organization_id = e.organization_id
133	    WHERE ei.organization_id = ${organizationId}
134	      AND ei.namespace = ${SLACK_IDENTITY.USER_ID}
135	      AND ei.identifier = ${identifier}
136	      AND ei.deleted_at IS NULL
137	      AND e.id = ei.entity_id
138	      AND e.organization_id = ei.organization_id
139	      AND et.slug = 'person'
140	    RETURNING ei.id
141	  `;
142		if (adopted.length > 0) return "adopted";
143	
144		const mine = await sql<{ id: number }>`
145	    SELECT id FROM entity_identities
146	    WHERE organization_id = ${organizationId}
147	      AND namespace = ${SLACK_IDENTITY.USER_ID}
148	      AND identifier = ${identifier}
149	      AND entity_id = ${memberEntityId}
150	      AND deleted_at IS NULL
151	    LIMIT 1
152	  `;
153		return mine.length > 0 ? "already-owned" : "conflict";
154	}
