  1327	async function handleDelete(
  1328		entityId: number,
  1329		force: boolean,
  1330		env: Env,
  1331		ctx: ToolContext,
  1332		args?: ManageEntityArgs,
  1333	): Promise<ManageEntityResult> {
  1334		// Get entity info before deletion
  1335		const entity = await getEntity(entityId, env, ctx);
  1336		if (!entity) {
  1337			throw new ToolUserError(`Entity with ID ${entityId} not found`, 404);
  1338		}
  1339	
  1340		const deleteActor = await actingPrincipalFor(args, ctx);
  1341		const attribution = attributionFor(deleteActor);
  1342		const current = {
  1343			id: entity.id,
  1344			entity_type: entity.entity_type,
  1345			name: entity.name,
  1346			slug: entity.slug,
  1347			parent_id: entity.parent_id,
  1348			metadata: entity.metadata ?? {},
  1349		};
  1350		const deleteDecision = await runMutationGate({
  1351			action: "delete",
  1352			organizationId: ctx.organizationId,
  1353			principalKind: deleteActor.kind,
  1354			sql: getDb(),
  1355			attribution,
  1356			// Trusted reaction-session watcher/window WINS — see the create path.
  1357			watcherId: ctx.actingWatcherId ?? args?.behavior_source?.behavior_id ?? null,
  1358			windowId: ctx.actingWindowId ?? args?.behavior_source?.window_id ?? null,
  1359			principalId: deleteActor.id,
  1360			ownerAgentId: deleteActor.ownerAgentId,
  1361			ownerResolved: deleteActor.ownerResolved,
  1362			entityTypeSlug: entity.entity_type,
  1363			entityId,
  1364			entityOrgId: null,
  1365			forceDeleteTree: force,
  1366			current,
  1367		});
  1368		if (deleteDecision.outcome === "deny") {
  1369			throw new ToolUserError(deleteDecision.reason, 403);
  1370		}
  1371		// Preflight: report what the delete would remove/detach without mutating.
  1372		// Runs after the gate's deny check (a denied principal gets no preview) but
  1373		// before defer queues anything — a dry run must never create an approval.
  1374		if (args?.dry_run) {
  1375			const preview = await deleteEntity(entityId, force, env, ctx, {
  1376				dryRun: true,
  1377			});
  1378			return {
  1379				action: "delete",
  1380				success: true,
  1381				message:
  1382					deleteDecision.outcome === "defer"
  1383						? `${preview.message} (a real delete would be queued for approval)`
  1384						: preview.message,
  1385				deleted_count: 0,
  1386				dry_run: true,
  1387				tree: preview.tree,
  1388			};
  1389		}
  1390		if (deleteDecision.outcome === "defer") {
  1391			const res = await deleteDecision.deferred.queue(ctx, env);
  1392			return {
  1393				action: "delete",
  1394				success: false,
  1395				message: `Delete queued for approval: ${entity.name}`,
  1396				deleted_count: 0,
  1397				approval_queued: true,
  1398				approval_url: res.approvalUrl,
  1399				approval_run_id: res.runId,
  1400				approval_action: "delete",
  1401				approval_proposal: {
  1402					entity_id: entity.id,
  1403					entity_type: entity.entity_type,
  1404					name: entity.name,
  1405					force_delete_tree: force,
  1406				},
  1407				approval_current: current,
  1408				approval_attribution: attribution,
  1409			} as ManageEntityResult;
  1410		}
  1411	
  1412		const result = await deleteEntity(entityId, force, env, ctx);
  1413	
  1414		return {
  1415			action: "delete",
  1416			success: true,
  1417			message: result.message,
  1418			deleted_count: result.deleted,
  1419			tree: result.tree,
  1420		};
  1421	}
