  1452	  JOIN entity_relationship_types rt ON r.relationship_type_id = rt.id
  1453	  LEFT JOIN entities fe ON r.from_entity_id = fe.id
  1454	  LEFT JOIN entity_types fet ON fet.id = fe.entity_type_id
