  1463	async function handleLink(
  1464		args: ManageEntityArgs,
  1465		env: Env,
  1466		ctx: ToolContext,
  1467	): Promise<ManageEntityResult> {
  1468		if (!args.from_entity_id)
  1469			throw new ToolUserError("from_entity_id is required for link", 400);
  1470		if (!args.to_entity_id)
  1471			throw new ToolUserError("to_entity_id is required for link", 400);
  1472		if (!args.relationship_type_slug)
  1473			throw new ToolUserError("relationship_type_slug is required for link", 400);
  1474	
  1475		const sql = getDb();
  1476	
  1477		validateNoSelfReference(args.from_entity_id, args.to_entity_id);
  1478		await validateScopeRule(args.from_entity_id, args.to_entity_id, env, ctx);
  1479	
  1480		// Schema search path for relationship types: tenant first, then any
  1481		// visibility='public' catalog. Mirrors createEntity's resolver so a tenant
  1482		// can use a canonical relationship type like `works_at` defined in
  1483		// public-uk-finance without registering a local copy. Tenant-local types
  1484		// win when both exist.
  1485		const typeRows = await sql`
  1486	    SELECT rt.id, rt.is_symmetric
  1487	    FROM entity_relationship_types rt
  1488	    LEFT JOIN organization o ON o.id = rt.organization_id
  1489	    WHERE rt.slug = ${args.relationship_type_slug}
  1490	      AND rt.deleted_at IS NULL
  1491	      AND (
  1492	        rt.organization_id = ${ctx.organizationId}
  1493	        OR o.visibility = 'public'
  1494	      )
  1495	    ORDER BY (rt.organization_id = ${ctx.organizationId}) DESC, rt.id ASC
  1496	    LIMIT 1
  1497	  `;
  1498	  if (typeRows.length === 0) {
  1499			throw new ToolUserError(
  1500				`Relationship type "${args.relationship_type_slug}" not found`,
  1501				404,
  1502			);
  1503	  }
  1504	  const typeId = Number(typeRows[0].id);
  1505	  const isSymmetric = Boolean(typeRows[0].is_symmetric);
  1506	
  1507	  await validateTypeRule(typeId, args.from_entity_id, args.to_entity_id, sql);
  1508	
  1509	  let fromId = args.from_entity_id;
  1510	  let toId = args.to_entity_id;
  1511	  if (isSymmetric) {
  1512	    // For symmetric same-org pairs we canonicalize by id so dedup catches
  1513	    // a → b and b → a as the same edge. For cross-org pairs (target in a
  1514	    // public catalog), keep the caller's-org entity as `from` even if its
  1515	    // id is higher, so the stored source matches the semantic source. The
  1516	    // canonical form would otherwise leave rows where `from_entity_id`
  1517	    // points at a public catalog row under a tenant `organization_id` —
  1518	    // tenant-owned but cosmetically inverted.
  1519	    const orgRows = await sql<{ id: number; organization_id: string }>`
  1520	      SELECT id, organization_id FROM entities WHERE id IN (${fromId}, ${toId})
  1521	    `;
  1522			const orgOf = (id: number) =>
  1523				String(orgRows.find((r) => Number(r.id) === id)?.organization_id);
  1524			const sameOrg =
  1525				orgOf(fromId) === ctx.organizationId &&
  1526				orgOf(toId) === ctx.organizationId;
  1527			if (sameOrg) {
  1528				const canonical = canonicalizeSymmetricEdge(fromId, toId);
  1529				fromId = canonical.from;
  1530				toId = canonical.to;
  1531			}
  1532			// else: cross-org symmetric — preserve caller-from / public-to.
  1533			// validateScopeRule already required `from` to be in caller's org.
  1534		}
  1535	
  1536		await checkDuplicateEdge(fromId, toId, typeId, sql);
  1537	
  1538		validateConfidence(args.confidence);
  1539		validateSource(args.source);
  1540		const source = args.source ?? "api";
  1541		const confidence =
  1542			args.confidence ?? (source === "ui" || source === "api" ? 1.0 : null);
  1543	
  1544		const inserted = await sql`
  1545	    INSERT INTO entity_relationships (
  1546	      organization_id, from_entity_id, to_entity_id, relationship_type_id,
  1547	      metadata, confidence, source, created_by, updated_by,
  1548	      created_at, updated_at
  1549	    ) VALUES (
  1550	      ${ctx.organizationId},
  1551	      ${fromId},
  1552	      ${toId},
  1553	      ${typeId},
  1554	      ${args.metadata ? sql.json(args.metadata) : null},
  1555	      ${confidence},
  1556	      ${source},
  1557	      ${ctx.userId},
  1558	      ${ctx.userId},
  1559	      current_timestamp,
  1560	      current_timestamp
  1561	    )
  1562	    RETURNING id
  1563	  `;
  1564	  const relationshipId = Number((inserted[0] as { id: unknown }).id);
  1565	
  1566	  const created = await sql.unsafe<RelationshipRow>(
  1567	    `SELECT ${RELATIONSHIP_SELECT} ${RELATIONSHIP_JOINS} WHERE r.id = $1`,
  1568			[relationshipId],
  1569	  );
  1570	
  1571		return { action: "link", relationship: created[0] };
  1572	}
