  1	/**
  2	 * The generic access-graph engine — ONE materializer behind every ACL source.
  3	 *
  4	 * A "source" (a Slack workspace, a GitHub org, later Jira/Drive/…) reduces to the
  5	 * same shape: a set of RESOURCES (channels, repos, projects), each with an
  6	 * AUDIENCE of MEMBERS who may read it. This engine takes that normalized shape
  7	 * and writes it into the existing entity graph — exactly the way the original
  8	 * `buildSlackChannelGraph` did, but with the resource/member specifics lifted
  9	 * into parameters so a second source reuses the whole body instead of copying it.
 10	 *
 11	 * It owns everything that was identical (or should have been) between the Slack
 12	 * channel graph and the GitHub team graph:
 13	 *   - resolve an org owner/admin to attribute entities/edges to (`created_by`);
 14	 *   - find-or-create the resource entity TYPE and the `member_of` relationship
 15	 *     type (reuse, no migration);
 16	 *   - resolve each resource to its entity, keyed on a source-specific identity
 17	 *     namespace (`slack_channel_id`, `github_repo_id`, …);
 18	 *   - resolve each member IDENTITY-FIRST and TYPE-AGNOSTICALLY — a member who has
 19	 *     already signed in owns their identity claim on a `$member` entity, so we
 20	 *     collapse onto THAT entity rather than forking a duplicate `person` (the
 21	 *     correctness fix the Slack builder had and the original GitHub builder did
 22	 *     NOT — folding GitHub onto this engine fixes it for free);
 23	 *   - write `member_of` (member → resource) edges idempotently;
 24	 *   - RECONCILE departures (soft-delete edges to a synced resource whose member is
 25	 *     no longer present) so leavers lose access on the next sync;
 26	 *   - stamp `authz_source_acl_state` ('full','fresh') so the gate begins enforcing
 27	 *     the connection.
 28	 *
 29	 * Tenant-scoped, idempotent, best-effort: everything filters on `organizationId`;
 30	 * edges dedupe on the live-triple unique index; nothing here throws on a
 31	 * data-shaped problem (the CALLER's fetch layer owns fail-closed-on-error).
 32	 */
 33	
 34	import { createLogger } from '@lobu/core';
 35	import {
 36	  ACL_RESOURCE_TYPE_SLUG,
 37	  type AccessIdentitySpec,
 38	  type AccessMember,
 39	  type AccessResource,
 40	} from '@lobu/connector-sdk';
 41	import { getDb, pgBigintArray, pgTextArray } from '../db/client.js';
 42	import { runtimeConnectionIdToSlug } from '../lobu/stores/connections-projection.js';
 43	import { resolveEventAttributionsForItems } from '../utils/entity-link-upsert.js';
 44	import { ensureResourceEntityType } from './acl-resource-type.js';
 45	
 46	const logger = createLogger('access-graph');
 47	
 48	const MEMBER_OF_TYPE_SLUG = 'member_of';
 49	
 50	export type { AccessIdentitySpec, AccessMember, AccessResource };
 51	export { ensureResourceEntityType } from './acl-resource-type.js';
 52	
 53	export interface AccessGraphResult {
 54	  /** Resource key → the entity id that now represents it. */
 55	  resourceEntityIds: Record<string, number>;
 56	  /** Distinct member entity ids that gained a `member_of` edge. */
 57	  memberEntityIds: number[];
 58	  createdEdges: number;
 59	  removedEdges: number;
 60	}
 61	
 62	const EMPTY_RESULT: AccessGraphResult = {
 63	  resourceEntityIds: {},
 64	  memberEntityIds: [],
 65	  createdEdges: 0,
 66	  removedEdges: 0,
 67	};
 68	
 69	/** Resolve an org owner/admin as `entities.created_by` / edge `created_by`
 70	 * (NOT NULL). Same query both source builders used. */
 71	async function resolveOrgCreator(orgId: string): Promise<string | null> {
 72	  const sql = getDb();
 73	  const rows = await sql<{ userId: string }>`
 74			SELECT "userId"
 75			FROM "member"
 76			WHERE "organizationId" = ${orgId}
 77			ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
 78			         "createdAt" ASC
 79			LIMIT 1
 80		`;
 81	  return rows.length > 0 ? rows[0].userId : null;
 82	}
 83	
 84	/** Ensure the org has a `person` entity type — the type new (genuinely-unknown)
 85	 * members are auto-created as. Prod seeds default types at org creation, but a
 86	 * brand-new/default org may not have it yet; without it those members would
 87	 * silently fail to resolve while the connection is still stamped enforced (their
 88	 * recall would then fail closed). */
 89	async function ensurePersonEntityType(orgId: string): Promise<void> {
 90	  const sql = getDb();
 91	  await sql`
 92			INSERT INTO entity_types (slug, name, organization_id, created_at, updated_at)
 93			VALUES ('person', 'Person', ${orgId}, current_timestamp, current_timestamp)
 94			ON CONFLICT (organization_id, slug) WHERE organization_id IS NOT NULL AND deleted_at IS NULL
 95			DO NOTHING
 96		`;
 97	}
 98	
 99	/** Find-or-create the org-scoped `member_of` relationship type. */
100	async function ensureMemberOfType(orgId: string): Promise<number> {
101	  const sql = getDb();
102	  const rows = await sql`
103			INSERT INTO entity_relationship_types
104				(slug, name, description, organization_id, is_symmetric, created_by, created_at, updated_at)
105			VALUES
106				(${MEMBER_OF_TYPE_SLUG}, 'Member of', 'A member belongs to an ACL resource (channel, repo, …)', ${orgId},
107				 false, NULL, current_timestamp, current_timestamp)
108			ON CONFLICT (organization_id, slug) WHERE status = 'active'
109			DO UPDATE SET updated_at = EXCLUDED.updated_at
110			RETURNING id
111		`;
112	  return Number(rows[0].id);
113	}
114	
115	/** Stamp the connection's ACL state so the gate begins enforcing it. */
116	async function markAclEnforced(orgId: string, connectionId: string): Promise<void> {
117	  const sql = getDb();
118	  await sql`
119			INSERT INTO authz_source_acl_state
120				(organization_id, connection_id, acl_support, freshness_state, last_synced_at, created_at, updated_at)
121			VALUES (${orgId}, ${connectionId}, 'full', 'fresh', current_timestamp, current_timestamp, current_timestamp)
122			ON CONFLICT (organization_id, connection_id)
123			DO UPDATE SET acl_support = 'full', freshness_state = 'fresh',
124			              last_synced_at = current_timestamp, updated_at = current_timestamp
125		`;
126	}
127	
128	/**
129	 * Resolve every distinct member to an entity id, IDENTITY-FIRST and
130	 * TYPE-AGNOSTIC: a member collapses onto any existing entity (`$member`,
131	 * `person`, …) carrying ANY of their identities; only genuinely-new members get
132	 * a freshly-created `person`. Returns a map member.key → entity id.
133	 */
134	async function resolveMembers(
135	  orgId: string,
136	  connectorKey: string,
137	  connectionId: number | null,
138	  members: AccessMember[],
139	  memberIdentities: AccessIdentitySpec[],
140	): Promise<Map<string, number>> {
141	  const byKey = new Map<string, number>();
142	  if (members.length === 0) return byKey;
143	
144	  // Gather identity values per namespace and look up existing owners (any type).
145	  const valuesByNamespace = new Map<string, Set<string>>();
146	  for (const m of members) {
147	    for (const id of m.identities) {
148	      if (!id.value) continue;
149	      const set = valuesByNamespace.get(id.namespace) ?? new Set<string>();
150	      set.add(id.value);
151	      valuesByNamespace.set(id.namespace, set);
152	    }
153	  }
154	  const existing = new Map<string, number>(); // `${namespace}|${value}` → entity id
155	  const sql = getDb();
156	  for (const [namespace, values] of valuesByNamespace) {
157	    const list = [...values];
158	    if (list.length === 0) continue;
159	    // The JOIN is load-bearing: an ordinary entity delete soft-deletes the
160	    // ENTITY but leaves its `entity_identities` rows live, still pointing at
161	    // it (only a merge or sign-in adoption repoints them). Matching on the
162	    // identity alone therefore resolves onto a dead entity, writes `member_of`
163	    // to it, and never mints a replacement — so the member silently vanishes
164	    // from the audience of every channel they are in. `lookupMatches` in
165	    // entity-link-upsert already joins for this reason; this matcher did not.
166	    const rows = await sql<{ identifier: string; entity_id: number }>`
167				SELECT ei.identifier, ei.entity_id
168				FROM entity_identities ei
169				JOIN entities e ON e.id = ei.entity_id
170				WHERE ei.organization_id = ${orgId}
171				  AND ei.namespace = ${namespace}
172				  AND ei.identifier = ANY(${pgTextArray(list)}::text[])
173				  AND ei.deleted_at IS NULL
174				  AND e.deleted_at IS NULL
175			`;
176	    for (const r of rows) {
177	      existing.set(`${namespace}|${String(r.identifier)}`, Number(r.entity_id));
178	    }
179	  }
180	
181	  // Which entity a member's claims resolve to follows the tier semantics the
182	  // create path below (`resolveEventAttributionsForItems`) already implements —
183	  // see `primary` in connector-types.ts. Stopping at the first array hit made
184	  // the answer depend on the order a connector pushed its identities, and
185	  // `member_of` is a read ACL, so that was a mis-grant waiting to happen: a
186	  // stale or recycled secondary claim (an old email, a reused login) would hand
187	  // one person another person's channel access. A PRESENT primary identity —
188	  // the source's stable per-account key — therefore governs alone and never
189	  // falls through to a secondary match: a fresh primary means a distinct
190	  // account even when a recycled secondary still points at the old person.
191	  // This fast path only claims a member when its answer matches what the
192	  // create-path engine would decide; every other case (primary present but
193	  // unmatched, a same-tier conflict) falls through to `toCreate`, where that
194	  // engine mints a new entity keyed on the primary or refuses the ambiguous
195	  // match outright (no edge — fail closed) with its 'merge candidate' warning.
196	  const primaryNamespaces = new Set(
197	    memberIdentities.filter((s) => s.primary).map((s) => s.namespace)
198	  );
199	  const toCreate: AccessMember[] = [];
200	  for (const m of members) {
201	    const primaryHits = new Set<number>();
202	    const secondaryHits = new Set<number>();
203	    let primaryPresent = false;
204	    for (const id of m.identities) {
205	      if (!id.value) continue;
206	      const isPrimary = primaryNamespaces.has(id.namespace);
207	      if (isPrimary) primaryPresent = true;
208	      const found = existing.get(`${id.namespace}|${id.value}`);
209	      if (found === undefined) continue;
210	      (isPrimary ? primaryHits : secondaryHits).add(found);
211	    }
212	    let hit: number | undefined;
213	    if (primaryPresent) {
214	      if (primaryHits.size === 1) {
215	        hit = [...primaryHits][0];
216	        const overridden = [...secondaryHits].filter((id) => id !== hit);
217	        if (overridden.length > 0) {
218	          logger.warn(
219	            {
220	              organization_id: orgId,
221	              connector_key: connectorKey,
222	              member_key: m.key,
223	              resolved_to: hit,
224	              overridden_entity_ids: overridden,
225	            },
226	            'access-graph: member matched multiple entities — resolved via the primary identity'
227	          );
228	        }
229	      }
230	    } else if (secondaryHits.size === 1) {
231	      hit = [...secondaryHits][0];
232	    }
233	    if (hit !== undefined) byKey.set(m.key, hit);
234	    else toCreate.push(m);
235	  }
236	
237	  if (toCreate.length === 0) return byKey;
238	
239	  // Auto-create a `person` for each genuinely-new member, carrying ALL their
240	  // declared identities so a later source (or login) collapses onto them.
241	  const items = toCreate.map((m) => {
242	    const metadata: Record<string, unknown> = { display_name: m.name ?? m.key };
243	    for (const id of m.identities) metadata[id.namespace] = id.value;
244	    return { origin_type: 'access_member', metadata };
245	  });
246	  const resolved = await resolveEventAttributionsForItems({
247	    connectorKey,
248	    connectionId,
249	    orgId,
250	    items,
251	    rules: {
252	      access_member: [
253	        {
254	          role: 'authored_by',
255	          entityType: 'person',
256	          autoCreate: true,
257	          titlePath: 'metadata.display_name',
258	          identities: memberIdentities.map((spec) => ({
259	            namespace: spec.namespace,
260	            eventPath: `metadata.${spec.namespace}`,
261	            primary: spec.primary,
262	          })),
263	        },
264	      ],
265	    },
266	  });
267	  for (let i = 0; i < toCreate.length; i++) {
268	    const ids = resolved.get(i);
269	    if (ids && ids.length > 0) byKey.set(toCreate[i].key, ids[0]);
270	  }
271	  return byKey;
272	}
273	
274	/**
275	 * Materialize a source's resource→audience graph and mark the connection
276	 * ACL-enforced. The CALLER normalizes its raw API shape into `resources`
277	 * (Slack channels with `T:C`/`T:U` keys, GitHub repos with collaborators, …);
278	 * this body is source-agnostic.
279	 */
280	export async function buildAccessGraph(params: {
281	  organizationId: string;
282	  connectionId: string;
283	  connectorKey: string;
284	  /** Identity namespace for resource keys (e.g. `slack_channel_id`). */
285	  resourceNamespace: string;
286	  memberIdentities: AccessIdentitySpec[];
287	  resources: AccessResource[];
288	}): Promise<AccessGraphResult> {
289	  const { organizationId, connectionId, connectorKey, resourceNamespace, memberIdentities } =
290	    params;
291	  const resources = params.resources.filter((r) => r.key);
292	  if (resources.length === 0) return EMPTY_RESULT;
293	
294	  const creatorUserId = await resolveOrgCreator(organizationId);
295	  if (!creatorUserId) {
296	    logger.warn(
297	      { organization_id: organizationId, connector: connectorKey },
298	      'Access graph skipped: org has no member to attribute as entity creator',
299	    );
300	    return EMPTY_RESULT;
301	  }
302	
303	  await ensureResourceEntityType(organizationId);
304	  await ensurePersonEntityType(organizationId);
305	
306	  // ACL state uses a runtime connection id, while identity provenance references
307	  // the stored numeric row. Resolve by slug (chat connections) or id text (data
308	  // connectors) without assuming the runtime id itself is numeric.
309	  const [storedConnection] = await getDb()<{ id: number }>`
310	    SELECT id
311	    FROM connections
312	    WHERE organization_id = ${organizationId}
313	      AND connector_key = ${connectorKey}
314	      AND deleted_at IS NULL
315	      AND (
316	        slug = ${runtimeConnectionIdToSlug(connectionId)}
317	        OR id::text = ${connectionId}
318	      )
319	    LIMIT 1
320	  `;
321	  const identityConnectionId = storedConnection
322	    ? Number(storedConnection.id)
323	    : null;
324	
325	  // 1) Resolve every resource to its entity, keyed on the source identity namespace.
326	  const resourceItems = resources.map((r) => ({
327	    origin_type: 'access_resource',
328	    metadata: { resource_key: r.key, resource_name: r.name ?? r.key },
329	  }));
330	  const resolvedResources = await resolveEventAttributionsForItems({
331	    connectorKey,
332	    connectionId: identityConnectionId,
333	    orgId: organizationId,
334	    items: resourceItems,
335	    rules: {
336	      access_resource: [
337	        {
338	          role: 'belongs_to',
339	          entityType: ACL_RESOURCE_TYPE_SLUG,
340	          autoCreate: true,
341	          titlePath: 'metadata.resource_name',
342	          identities: [
343	            {
344	              namespace: resourceNamespace,
345	              eventPath: 'metadata.resource_key',
346	              primary: true,
347	            },
348	          ],
349	        },
350	      ],
351	    },
352	  });
353	  const resourceEntityIds: Record<string, number> = {};
354	  const resourceEntityIdByIndex = new Map<number, number>();
355	  for (let i = 0; i < resources.length; i++) {
356	    const ids = resolvedResources.get(i);
357	    if (ids && ids.length > 0) {
358	      resourceEntityIds[resources[i].key] = ids[0];
359	      resourceEntityIdByIndex.set(i, ids[0]);
360	    }
361	  }
362	
363	  // 2) Resolve every DISTINCT member (identity-first, type-agnostic).
364	  const distinctMembers = new Map<string, AccessMember>();
365	  for (const r of resources) {
366	    for (const m of r.members) {
367	      if (m.key && !distinctMembers.has(m.key)) distinctMembers.set(m.key, m);
368	    }
369	  }
370	  const memberEntityByKey = await resolveMembers(
371	    organizationId,
372	    connectorKey,
373	    identityConnectionId,
374	    [...distinctMembers.values()],
375	    memberIdentities,
376	  );
377	
378	  // 3) Write member → resource `member_of` edges, idempotent on the live-triple
379	  // unique index. Accumulate the CURRENT member set per resource for reconcile.
380	  const typeId = await ensureMemberOfType(organizationId);
381	  const sql = getDb();
382	
383	  // Keep each resource entity's display name fresh. `titlePath` only sets the
384	  // name on auto-CREATE, so a name that wasn't available at first graph (or a
385	  // later channel/repo RENAME) would otherwise stick to the stale value / the
386	  // raw id. Refresh from the source-provided name here. Scoped to the resources
387	  // in this build; idempotent (the `name <>` guard no-ops when unchanged).
388	  for (let i = 0; i < resources.length; i++) {
389	    const id = resourceEntityIdByIndex.get(i);
390	    const name = resources[i].name;
391	    if (id && name) {
392	      await sql`
393	        UPDATE entities
394	        SET name = ${name}, updated_at = current_timestamp
395	        WHERE id = ${id}
396	          AND organization_id = ${organizationId}
397	          AND name <> ${name}
398	          AND deleted_at IS NULL
399	      `;
400	    }
401	  }
402	
403	  const memberEntityIds = new Set<number>();
404	  const currentMembersByResource = new Map<number, Set<number>>();
405	  let createdEdges = 0;
406	  for (let i = 0; i < resources.length; i++) {
407	    const resourceEntityId = resourceEntityIdByIndex.get(i);
408	    if (resourceEntityId === undefined) continue;
409	    const resourceMembers = currentMembersByResource.get(resourceEntityId) ?? new Set<number>();
410	    currentMembersByResource.set(resourceEntityId, resourceMembers);
411	    for (const m of resources[i].members) {
412	      const memberEntityId = memberEntityByKey.get(m.key);
413	      if (memberEntityId === undefined) continue;
414	      memberEntityIds.add(memberEntityId);
415	      resourceMembers.add(memberEntityId);
416	      const inserted = await sql<{ id: number }[]>`
417					INSERT INTO entity_relationships (
418						organization_id, from_entity_id, to_entity_id, relationship_type_id,
419						confidence, source, created_by, updated_by, created_at, updated_at
420					) VALUES (
421						${organizationId}, ${memberEntityId}, ${resourceEntityId}, ${typeId},
422						1.0, 'feed', ${creatorUserId}, ${creatorUserId},
423						current_timestamp, current_timestamp
424					)
425					ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
426						WHERE deleted_at IS NULL
427					DO NOTHING
428					RETURNING id
429				`;
430	      if (inserted.length > 0) createdEdges += 1;
431	    }
432	  }
433	
434	  // 4) Reconcile DEPARTURES — the build is a full re-sync of each resource's
435	  // membership, so a `member_of` edge to a synced resource whose member is NOT
436	  // in the current set means that person left: soft-delete it so they lose
437	  // access immediately. Scoped to `to_entity_id` = a resource we just synced, so
438	  // edges to OTHER resource types (a different source's graph) are never touched.
439	  // An empty member set deletes all of that resource's edges — the caller must
440	  // not pass empty-on-fetch-error.
441	  let removedEdges = 0;
442	  for (const [resourceEntityId, resourceMembers] of currentMembersByResource) {
443	    const keep = [...resourceMembers];
444	    const removed = await sql<{ id: number }[]>`
445				UPDATE entity_relationships
446				SET deleted_at = current_timestamp, updated_at = current_timestamp
447				WHERE organization_id = ${organizationId}
448				  AND relationship_type_id = ${typeId}
449				  AND to_entity_id = ${resourceEntityId}
450				  AND deleted_at IS NULL
451				  AND from_entity_id <> ALL(${pgBigintArray(keep)}::bigint[])
452				RETURNING id
453			`;
454	    removedEdges += removed.length;
455	  }
456	
457	  await markAclEnforced(organizationId, connectionId);
458	
459	  logger.info(
460	    {
461	      organization_id: organizationId,
462	      connection_id: connectionId,
463	      connector: connectorKey,
464	      resource_type: ACL_RESOURCE_TYPE_SLUG,
465	      resource_namespace: resourceNamespace,
466	      resources: Object.keys(resourceEntityIds).length,
467	      members: memberEntityIds.size,
468	      created_edges: createdEdges,
469	      removed_edges: removedEdges,
470	    },
471	    'Built access graph',
472	  );
473	
474	  return {
475	    resourceEntityIds,
476	    memberEntityIds: [...memberEntityIds],
477	    createdEdges,
478	    removedEdges,
479	  };
480	}

