642		if (actor.kind === "user" && !isAdminOrOwnerRole(ctx.memberRole)) {
643			throw new ToolUserError("Only an admin or owner may merge entities", 403);
644		}
645		const loserIds = [
646			...new Set(
647				args.duplicate_entity_ids ?? (args.entity_id ? [args.entity_id] : []),
648			),
649		].sort((a, b) => a - b);
650		const winnerId = args.winner_entity_id;
651		if (loserIds.length === 0)
652			throw new ToolUserError(
653				"entity_id or duplicate_entity_ids is required for merge",
654				400,
655			);
656		if (!winnerId)
657			throw new ToolUserError(
658				"winner_entity_id (the survivor) is required for merge",
659				400,
660			);
661		if (loserIds.includes(winnerId))
662			throw new ToolUserError("winner_entity_id cannot also be a duplicate", 400);
663		if (loserIds.length > 25)
