665	
666		const sql = getDb();
667		// Every duplicate and the winner must be live and in the caller's org — never
668		// merge across a tenant boundary or into a deleted/foreign entity.
669		const rows = (await sql`
670	    SELECT e.id, e.entity_type_id, e.metadata, et.metadata_schema,
671	           et.slug AS entity_type_slug
