     1	/**
     2	 * Shared ACL-enforcement-state helpers — used by BOTH read gates (the Slack
     3	 * channel gate `./channel-visibility` and the generic resource gate
     4	 * `./resource-visibility`) AND the audience read (`./audience`) so the "is this
     5	 * connection enforcing right now?" rule and the team-scoped channel key live in
     6	 * one place and cannot drift between them.
     7	 */
     8	
     9	import { type DbClient, pgTextArray } from "../db/client.js";
    10	import { stripPlatformPrefix } from "../gateway/channels/bound-channels.js";
    11	import { channelReadIdentityFor } from "./sources.js";
    12	
    13	/**
    14	 * How long a `fresh` ACL graph stays trusted without a re-sync. The background
    15	 * sync re-stamps `last_synced_at`; if it stops, a connection's graph ages past
    16	 * this window and the gate stops trusting it — failing closed rather than
    17	 * serving stale membership. Generous vs. the ~15-min sync cadence so a transient
    18	 * hiccup never blinks recall off.
    19	 */
    20	export const ACL_STALE_AFTER_MINUTES = 60;
    21	
    22	/**
    23	 * SQL subquery (no leading/trailing space) selecting the `connection_id`s that
    24	 * are ACL-enforced right now: `acl_support='full'` AND `freshness_state='fresh'`
    25	 * AND synced within {@link ACL_STALE_AFTER_MINUTES}. `orgParam` is an already-bound
    26	 * `$N::text` placeholder. Returns the bare `SELECT …` (caller wraps in IN/NOT IN).
    27	 */
    28	export function enforcedConnectionsSelectSql(orgParam: string): string {
    29	  return `SELECT connection_id FROM public.authz_source_acl_state
    30	    WHERE organization_id = ${orgParam}
    31	      AND acl_support = 'full'
    32	      AND freshness_state = 'fresh'
    33	      AND last_synced_at IS NOT NULL
    34	      AND last_synced_at >= current_timestamp - make_interval(mins => ${ACL_STALE_AFTER_MINUTES})`;
    35	}
    36	
    37	/**
    38	 * SQL subquery (no leading/trailing space) selecting the `connection_id`s that
    39	 * have ANY `authz_source_acl_state` row — i.e. every connection ONBOARDED into
    40	 * authz, regardless of whether it is currently enforcing. The complement
    41	 * (`NOT IN` this set) is the "never graphed → legacy fence" case; a connection
    42	 * that IS in this set but NOT in {@link enforcedConnectionsSelectSql} is
    43	 * onboarded-but-stale and must fail closed. `orgParam` is an already-bound
    44	 * `$N::text` placeholder. Returns the bare `SELECT …` (caller wraps in IN/NOT IN).
    45	 */
    46	export function aclStateExistsSelectSql(orgParam: string): string {
    47	  return `SELECT connection_id FROM public.authz_source_acl_state
    48	    WHERE organization_id = ${orgParam}`;
    49	}
    50	
    51	/**
    52	 * Per-connection enforcement state, the single shape BOTH the gate
    53	 * (`./channel-visibility`) and the audience read (`./audience`) project from the
    54	 * `authz_source_acl_state` row:
    55	 *  - `enforced`    — `acl_support='full'` AND `freshness_state='fresh'` AND synced
    56	 *                    within {@link ACL_STALE_AFTER_MINUTES}; recall is membership-gated.
    57	 *  - `stale`       — onboarded (a row exists) but not currently enforcing
    58	 *                    (partial/stale/aged-out) → fails closed.
    59	 *  - `not-graphed` — no row at all (a connection ABSENT from
    60	 *                    {@link getConnectionEnforcement}'s map); legacy per-agent fence.
    61	 */
    62	export type EnforcementStatus = "enforced" | "stale" | "not-graphed";
    63	
    64	export interface ChannelEnforcement {
    65	  status: EnforcementStatus;
    66	  aclSupport: string | null;
    67	  freshnessState: string | null;
    68	  lastSyncedAt: string | null;
    69	}
    70	
    71	/** The state for a connection with no `authz_source_acl_state` row. */
    72	export const NOT_GRAPHED: ChannelEnforcement = {
    73	  status: "not-graphed",
    74	  aclSupport: null,
    75	  freshnessState: null,
    76	  lastSyncedAt: null,
    77	};
    78	
    79	/**
    80	 * Resolve each connection's enforcement state. A connection ABSENT from the
    81	 * returned map has no `authz_source_acl_state` row — it was never graphed, so it
    82	 * keeps the legacy per-agent fence ({@link NOT_GRAPHED}). A connection PRESENT is
    83	 * either `enforced` (full+fresh+in-window) or `stale` (anything else, which fails
    84	 * closed). This is the ONE place the enforce predicate is evaluated for the
    85	 * parameterized read paths, so the gate and the audience can never disagree.
    86	 */
    87	export async function getConnectionEnforcement(
    88	  sql: DbClient,
    89	  organizationId: string,
    90	  connectionIds: string[],
    91	): Promise<Map<string, ChannelEnforcement>> {
    92	  const ids = [...new Set(connectionIds)].filter(Boolean);
    93	  if (ids.length === 0) return new Map();
    94	  const rows = await sql<{
    95	    connection_id: string;
    96	    acl_support: string | null;
    97	    freshness_state: string | null;
    98	    last_synced_at: Date | null;
    99	    enforce: boolean;
   100	  }>`
   101	    SELECT
   102	      connection_id,
   103	      acl_support,
   104	      freshness_state,
   105	      last_synced_at,
   106	      (
   107	        acl_support = 'full'
   108	        AND freshness_state = 'fresh'
   109	        AND last_synced_at IS NOT NULL
   110	        AND last_synced_at >= current_timestamp - make_interval(mins => ${ACL_STALE_AFTER_MINUTES})
   111	      ) AS enforce
   112	    FROM authz_source_acl_state
   113	    WHERE organization_id = ${organizationId}
   114	      AND connection_id = ANY(${pgTextArray(ids)}::text[])
   115	  `;
   116	  const out = new Map<string, ChannelEnforcement>();
   117	  for (const r of rows) {
   118	    out.set(String(r.connection_id), {
   119	      status: r.enforce === true ? "enforced" : "stale",
   120	      aclSupport: r.acl_support ?? null,
   121	      freshnessState: r.freshness_state ?? null,
   122	      lastSyncedAt: r.last_synced_at
   123	        ? new Date(r.last_synced_at).toISOString()
   124	        : null,
   125	    });
   126	  }
   127	  return out;
   128	}
   129	
   130	/** A row carrying the fields needed to form a team-scoped channel key. */
   131	export interface ChannelKeyRow {
   132	  platform: string;
   133	  /** As stored on the binding — may be platform-prefixed (`slack:C…`) or bare. */
   134	  channel_id: string;
   135	  /** Workspace/tenant id (Slack `T…`); required to form the key. */
   136	  team_id: string | null;
   137	}
   138	
   139	/**
   140	 * The team-scoped channel key (`T…:C…`) for a bound row, or null when the row's
   141	 * platform has no enforced channel gate or has no team id (can't be keyed → the
   142	 * gate drops it fail-closed, the audience reports an empty member set). The ONE
